set nh_guard_tcltest_skip [::tcltest::configure -skip]
set nh_guard_tcltest_verbose [::tcltest::configure -verbose]
::tcltest::configure -match wiki-upvar-1 -skip {}
list ownership-guard execution-namespace $nh_guard_scope absent $nh_guard_absent selected wiki-upvar-1 tcltest [package present tcltest]

