        set prefix [list take {x; error injected}]
        eval [linsert $prefix end {a b}]
    }
} -result {{x; error injected} {a b}}

::tcltest::test wiki-prefix-2 {script and list prefix treat newline differently} -constraints tcl85 -body {
    isolated {
